const isChordLine=(line:string)=>{const tokens=line.trim().split(/\s+/);return tokens.length>0 && tokens.every(t=>/^[A-G](?:#|b)?(?:m|maj|min|sus|dim|aug|add)?\d*(?:\/[A-G](?:#|b)?)?$/.test(t));};
function parseChordText(raw:string){const lines=raw.replace(/\r/g,'').split('\n');const chordLines:string[]=[];const lyricLines:string[]=[];let section='';const sections:string[]=[];for(const line of lines){const t=line.trim();if(!t){lyricLines.push('');continue;}if(isChordLine(t)){chordLines.push(t);if(section)sections.push(`${section} — ${t}`);continue;}if(/^(INTRO|ESTROFA|VERSO|PRE CORO|PRECoro|CORO|PUENTE|BRIDGE|INSTRUMENTAL|FINAL|OUTRO)/i.test(t)){section=t;sections.push(t); }lyricLines.push(line);}return {lyrics:lyricLines.join('\n').trim(),chords:chordLines.join('\n'),sections:sections.join('\n')};}
function canonicalSectionLabel(input:string){
 const original=input.trim();
 const match=original.match(/^([^(]+?)(\s*\([^)]*\))?$/);
 const head=(match?.[1]||original).trim();
 const suffix=match?.[2]||'';
 const normalized=head.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[._-]/g,' ').replace(/\s+/g,' ').trim();
 const aliases:[RegExp,string][]=[
  [/^(intro|introduction|introduccion)$/,'INTRO'],
  [/^(estrofa|verso|verse|parte\s*\d+)\s*\d*$/,'ESTROFA'],
  [/^(pre coro|pre-coro|precoro|pre chorus|pre-chorus|pre estribillo|preestribillo)$/,'PRE CORO'],
  [/^(coro|estribillo|chorus)$/,'CORO'],
  [/^(puente|bridge)$/,'PUENTE'],
  [/^(instrumental|interludio|interlude)$/,'INSTRUMENTAL'],
  [/^(final|outro|cierre)$/,'FINAL'],
 ];
 let base=head;
 for(const [re,label] of aliases){if(re.test(normalized)){base=label;break;}}
 const num=normalized.match(/(?:estrofa|verso|verse|parte)\s*(\d+)/)?.[1] || head.match(/\b(\d+)\b/)?.[1];
 if(base==='ESTROFA' && num) base+=` ${num}`;
 return base+suffix;
}
function normalizeSectionLines(block:string, mode:'lyrics'|'mixed'|'guide'){
 const lines=block.replace(/\r/g,'').split('\n');
 let verseCount=0, chorusCount=0;
 return lines.map(line=>{
  const t=line.trim(); if(!t)return line;
  if(mode==='guide'){
   const m=t.match(/^([^(:]+?)(\s*\([^)]*\))?(\s*[:：].*)?$/);
   if(m && /^(estrofa|verso|verse|parte\s*\d+|pre\s*coro|pre-chorus|pre chorus|pre estribillo|coro|estribillo|chorus|puente|bridge|instrumental|intro|final|outro)/i.test(m[1].trim())){
    const label=canonicalSectionLabel(m[1].trim()+(m[2]||''));
    return label+(m[3]||'');
   }
   return line;
  }
  const heading=t.replace(/:$/,'');
  if(/^(estrofa|verso|verse|parte\s*\d+|pre\s*coro|pre-chorus|pre chorus|pre estribillo|coro|estribillo|chorus|puente|bridge|instrumental|intro|final|outro)(\s*\d+)?$/i.test(heading)){
   const normalized=canonicalSectionLabel(heading);
   if(/^ESTROFA$/i.test(normalized)){verseCount++;return `ESTROFA ${verseCount}`;}
   if(/^CORO$/i.test(normalized)){chorusCount++;return `CORO ${chorusCount}`;}
   return normalized;
  }
  return line;
 }).join('\n').trim();
}

// Reconstruye las líneas usando las coordenadas de cada palabra detectada por Tesseract.
// Esto conserva la separación vertical entre acordes y letra, en lugar de aplanar todo el OCR.
function ocrWordsToMusicalText(words:any[]){
 const valid=(w:any)=>typeof w.text==='string'&&w.text.trim()&&w.bbox;
 const items=words.filter(valid).map((w:any)=>({text:w.text.trim(),x:Number(w.bbox.x0)||0,y:(Number(w.bbox.y0)+Number(w.bbox.y1))/2,confidence:Number(w.confidence??0)})).filter((w:any)=>w.text);
 items.sort((a:any,b:any)=>a.y-b.y||a.x-b.x);
 const rows:any[]=[];
 for(const item of items){let row=rows.find(r=>Math.abs(r.y-item.y)<=Math.max(8, r.height*0.55));if(!row){row={y:item.y,height:12,items:[]};rows.push(row);}row.items.push(item);row.y=row.items.reduce((n:number,w:any)=>n+w.y,0)/row.items.length;}
 rows.sort((a:any,b:any)=>a.y-b.y);
 const chordToken=(value:string)=>/^[A-G](?:#|b)?(?:m|maj|min|sus|dim|aug|add)?\d*(?:\/[A-G](?:#|b)?)?$/.test(value.replace(/[|]/g,'/'));
 return rows.map((row:any)=>{
  row.items.sort((a:any,b:any)=>a.x-b.x);
  const tokens=row.items.map((w:any)=>w.text.replace(/[“”]/g,'"').replace(/[’]/g,"'"));
  const normalized=tokens.map((t:string)=>{const compact=t.replace(/[.,;:]$/,'');const fixes:Record<string,string>={'Cém':'C#m','C#m':'C#m','C#rn':'C#m','G#7':'G#7','G#/C':'G#/C','G#|C':'G#/C'};return fixes[compact]||t;});
  const allChords=normalized.length>0&&normalized.every((t:string)=>chordToken(t.replace(/[.,;:]$/,'')));
  if(allChords){let out='';let lastX=0;const base=row.items[0].x;for(let i=0;i<row.items.length;i++){const x=row.items[i].x-base;const target=Math.max(out.length,Math.round(x/8));if(target>out.length)out+=' '.repeat(Math.min(40,target-out.length));out+=normalized[i];lastX=row.items[i].x;}return out.trimEnd();}
  return normalized.join(' ').replace(/\s+([,.;!?])/g,'$1');
 }).filter((line:string)=>line.trim()&&!/^P[AÁ]GINA\s+\d+$/i.test(line.trim())).join('\n');
}

function parseImportedSong(raw:string){
 const text=raw.replace(/\u200b/g,'').replace(/\r/g,'').replace(/[\u00a0]/g,' ');
 const lines=text.split('\n');
 const meta=(label:string)=>{const re=new RegExp('^\\s*'+label+':\\s*(.+)$','im');return text.match(re)?.[1]?.trim()||'';};
 const norm=(v:string)=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/\s+/g,' ').trim();
 const findHeader=(names:string[])=>lines.findIndex(l=>{const m=l.match(/^\s*\[\s*([^\]]+)\s*\]\s*$/);return !!m&&names.includes(norm(m[1]));});
 const mixedStart=findHeader(['FORMATO MIXTO','MIXTO','FORMATO MIXTO ACORDES Y LETRA']);
 const lyricsStart=findHeader(['FORMATO LETRA','FORMATO LETRA COMPLETA','LETRA']);
 // El formato sencillo usa únicamente DATOS + MIXTO. Si recibe un documento antiguo,
 // toma exclusivamente su bloque MIXTO y nunca concatena las otras vistas.
 let bodyLines:string[]=[];
 if(mixedStart>=0){bodyLines=lines.slice(mixedStart+1);const next=bodyLines.findIndex(l=>/^\s*\[\s*FORMATO\s+(LETRA|ACORDES|GUIA)/i.test(l));if(next>=0)bodyLines=bodyLines.slice(0,next);}
 else if(lyricsStart>=0){bodyLines=lines.slice(lyricsStart+1);}
 else {const dataEnd=lines.findIndex(l=>/^\s*\[\s*DATOS/i.test(l));bodyLines=lines.slice(dataEnd>=0?dataEnd+1:0);}
 bodyLines=bodyLines.filter(l=>!/^\s*\[\s*(DATOS|FORMATO)/i.test(l));
 // Quitar título suelto inicial y líneas de metadatos que a veces Mammoth concatena.
 while(bodyLines.length && (!bodyLines[0].trim() || /^\s*(LIBRE SOY|NOMBRE:|ARTISTA:|TONALIDAD:|BPM:|CATEGORIA:|CATEGOR[IÍ]A:|ENLACE REFERENCIA:|LETRA:|ACORDES:)/i.test(bodyLines[0]))) bodyLines.shift();
 const sectionRe=/^(INTRO(?:DUCCI[ÓO]N)?|ESTROFA|VERSO|VERSE|PARTE\s*\d+|PRE\s*CORO|PRE-CORO|PRE-CHORUS|PRE CHORUS|PRE ESTRIBILLO|PREESTRIBILLO|CORO|ESTRIBILLO|CHORUS|PUENTE|BRIDGE|INSTRUMENTAL|INTERLUDIO|INTERLUDE|FINAL|OUTRO|CIERRE)(?:\s*(?:\d+|[IVXLCDM]+))?(?:\s*\([^)]*\))?\s*:?$/i;
 const canonical=(heading:string,counts:Record<string,number>)=>{
  const m=heading.trim().match(/^(.+?)(?:\s*\((.*?)\))?$/);let head=(m?.[1]||heading).replace(/:$/,'').trim();const suffix=m?.[2]?` (${m[2]})`:'';const n=head.match(/\d+/)?.[0];const k=norm(head).replace(/\s*(?:\d+|[IVXLCDM]+)$/,'');
  let base=k;
  if(/^(VERSO|VERSE|PARTE|ESTROFA)$/.test(k))base='ESTROFA';
  else if(/^(PRE CORO|PRE-CORO|PRE-CHORUS|PRE CHORUS|PRE ESTRIBILLO|PREESTRIBILLO)$/.test(k))base='PRE CORO';
  else if(/^(CORO|ESTRIBILLO|CHORUS)$/.test(k))base='CORO';
  else if(/^(BRIDGE)$/.test(k))base='PUENTE';
  else if(/^(INTERLUDIO|INTERLUDE)$/.test(k))base='INSTRUMENTAL';
  else if(/^(INTRODUCCION)$/.test(k))base='INTRO';
  if(base==='ESTROFA'||base==='CORO'){counts[base]=(counts[base]||0)+1;const roman=head.match(/\b([IVXLCDM]+)$/i)?.[1];const romanMap:Record<string,number>={I:1,II:2,III:3,IV:4,V:5,VI:6};return `${base} ${n|| (roman?romanMap[roman.toUpperCase()]||counts[base]:counts[base])}${suffix}`;}
  return base+suffix;
 };
 const chordLine=(line:string)=>isChordLine(line.trim());
 const counts:Record<string,number>={};const mixed:string[]=[];const lyric:string[]=[];const guideGroups:{heading:string;chords:string[]}[]=[];let currentSection='';let pendingChord='';
 for(let i=0;i<bodyLines.length;i++){
  const rawLine=bodyLines[i];const t=rawLine.trim();
  if(!t){if(mixed.length&&mixed[mixed.length-1]!=='')mixed.push('');if(lyric.length&&lyric[lyric.length-1]!=='')lyric.push('');continue;}
  if(/^LIBRE SOY$/i.test(t))continue;
  if(sectionRe.test(t)){
   currentSection=canonical(t,counts);mixed.push(currentSection);lyric.push(currentSection);guideGroups.push({heading:currentSection,chords:[]});pendingChord='';continue;
  }
  if(/^INTRO\s*:/i.test(t)){
   const progression=t.split(':').slice(1).join(':').trim();currentSection='INTRO';mixed.push(`INTRO: ${progression}`);guideGroups.push({heading:'INTRO',chords:progression?progression.split(/\s*-\s*/):[]});continue;
  }
  if(chordLine(t)){
   pendingChord=rawLine;
   if(currentSection){const group=guideGroups[guideGroups.length-1];if(group)group.chords.push(...t.split(/\s+/).filter(Boolean));}
   continue;
  }
  if(pendingChord){mixed.push(pendingChord);pendingChord='';}
  mixed.push(rawLine);lyric.push(rawLine);
 }
 const clean=(a:string[])=>a.join('\n').replace(/\n{3,}/g,'\n\n').trim();
 // Si no hay acordes detectables, se conserva el contenido para revisión y no se inventa.
 const guide=guideGroups.map(g=>g.heading+(g.chords.length?'\n'+g.chords.join(' - '):'')).join('\n\n');
 return {title:meta('NOMBRE'),artist:meta('ARTISTA'),key:meta('TONALIDAD'),bpm:meta('BPM'),category:meta('CATEGOR[IÍ]A'),reference:meta('ENLACE REFERENCIA'),lyrics:clean(lyric),mixedText:clean(mixed),sections:guide,chords:guideGroups.flatMap(g=>g.chords).join('\n')};
}

