 const [meetingDraft,setMeetingDraft]=useState<Meeting|null>(null); const [meetingFunctionDraft,setMeetingFunctionDraft]=useState<Record<string,string[]>>({}); const [meetingFormLoading,setMeetingFormLoading]=useState(false); const [meetingAssignmentLoadError,setMeetingAssignmentLoadError]=useState(''); const [meetingSaving,setMeetingSaving]=useState(false);
 useEffect(()=>{localStorage.setItem('unara.theme.'+userId,JSON.stringify(dark))},[dark,userId]);
